/**
 * A project is searchable only while it is live. An issue is searchable only
 * while both the issue and its project are live. A comment is searchable only
 * while the comment, its issue and that issue's project are all live.
 * Anything else is removed, so archive, restore and rebuild share one rule.
 */
async function projectIsSearchable(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<boolean> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  return project !== null && isLive(project);
}

export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  if (!isLive(issue) || !(await projectIsSearchable(orgId, issue.projectId))) {
    await removeFromIndex(orgId, "issue", issue.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    issue.id,
    [issue.title, issue.description ?? ""].join("\n"),
    issue.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const issue = await issueRepo.findIssueById(orgId, comment.issueId);
  if (
    !isLive(comment) ||
    issue === null ||
    !isLive(issue) ||
    !(await projectIsSearchable(orgId, issue.projectId))
  ) {
    await removeFromIndex(orgId, "comment", comment.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    comment.id,
    comment.body,
    issue.projectId,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  if (!isLive(project)) {
    await removeFromIndex(orgId, "project", project.id);
    return;
  }

  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    project.id,
    [project.name, project.description ?? ""].join("\n"),
    project.id,
  );
}

async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  const seen = new Set<string>();

  for (;;) {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    if (page.nextCursor === null || seen.has(page.nextCursor)) return;
    seen.add(page.nextCursor);
    cursor = page.nextCursor;
  }
}

/** Re-applies the visibility rule to every comment on one issue. */
async function syncIssueComments(orgId: OrgId, issueId: IssueId): Promise<void> {
  await eachPage(
    (cursor) =>
      commentRepo.listComments({
        orgId,
        issueId,
        includeArchived: true,
        limit: INDEX_PAGE_SIZE,
        cursor,
      }),
    (comment) => indexComment(orgId, comment),
  );
}

/**
 * Re-applies the visibility rule to a project, every issue in it (archived
 * or not) and every comment on those issues. Restoring a project therefore
 * brings back only issues that are still live, and their live comments.
 */
async function syncProjectTree(orgId: OrgId, projectId: ProjectId): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project) {
    await indexProject(orgId, project);
  } else {
    await removeFromIndex(orgId, "project", projectId);
  }

  await eachPage(
    (cursor) =>
      issueRepo.listIssues({
        orgId,
        projectId,
        includeArchived: true,
        limit: INDEX_PAGE_SIZE,
        cursor,
      }),
    async (issue) => {
      await indexIssue(orgId, issue);
      await syncIssueComments(orgId, issue.id);
    },
  );
}

