/**
 * Walks every page of one tenant's projects, issues and comments. Scoped to a
 * single org on purpose: a full-fleet reindex is a sequence of these, so one
 * slow tenant cannot stall the rest, and another tenant's documents are never
 * deleted or rewritten.
 *
 * The org's index is cleared first, then every row — including archived ones —
 * is handed to the index writers. Those writers decide what is searchable, so
 * a rebuild cannot resurrect an archived project, an archived issue, or a
 * deleted comment, and it cannot stop after the first page of a large org.
 */
async function eachPage<T>(
  load: (cursor: string | null) => Promise<Page<T>>,
  visit: (item: T) => Promise<void>,
): Promise<void> {
  let cursor: string | null = null;
  const seen = new Set<string>();

  for (;;) {
    const page = await load(cursor);
    for (const item of page.items) {
      await visit(item);
    }
    if (page.nextCursor === null || seen.has(page.nextCursor)) return;
    seen.add(page.nextCursor);
    cursor = page.nextCursor;
  }
}

